// evals/results.md is the two suite reports back to back: frozen v1 first,
// then v2. Each suite writes its own file; this stitches them together.

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

export function composeResults() {
  const parts = ["v1", "v2"]
    .map((suite) => path.join(__dirname, suite, "results.md"))
    .filter((file) => existsSync(file))
    .map((file) => readFileSync(file, "utf8").trim());
  const header = [
    "<!-- Generated by `npm run eval` (v2) and `npm run eval:v1`. Do not edit by hand. -->",
    "",
    "This file has two parts. **Eval v1** is frozen: its cases, checks and answers do not change. **Eval v2** follows it and measures changes made after v1 was frozen, with its own cases and runs.",
    "",
    "",
  ].join("\n");
  writeFileSync(path.join(__dirname, "results.md"), header + parts.join("\n\n---\n\n") + "\n");
}
